insert into SqlTemplate (ActionKey, Sql, ParamTypes, RecordType, RecordDecl, KeyField, CallerScope, Filter, OrderBy, Rules, TestBounds, ReadGroups, WriteGroups) values ('GetInvoicesSince', 'select i.ID as ID, c.Name as Name, i.Amount as Amount, i.InvoiceDate as InvoiceDate from Invoice i inner join Customer c on c.ID = i.CustomerID where i.InvoiceDate >= ? order by i.InvoiceDate;', 'date', '', '', '', '', '', '', '', '["2025-01-01"]', 1, 0);
