insert into SqlTemplate (ActionKey, Sql, ParamTypes, RecordType, RecordDecl, KeyField, CallerScope, Filter, OrderBy, Rules, TestBounds, ReadGroups, WriteGroups) values ('GetStundenProProjekt', 'select p.Titel as Titel, p.Budget as Budget, count(z.ID) as Buchungen, sum(z.Stunden) as Stunden from Projekt p inner join Zeitbuchung z on z.ProjektID = p.ID group by p.ID, p.Titel, p.Budget order by Stunden desc;', '', '', '', '', '', '', '', '', '[]', 1, 0);
insert into SqlTemplate (ActionKey, Sql, ParamTypes, RecordType, RecordDecl, KeyField, CallerScope, Filter, OrderBy, Rules, TestBounds, ReadGroups, WriteGroups) values ('GetTurnoverPerCustomer', 'select c.Name as Name, c.City as City, count(i.ID) as InvoiceCount, sum(i.Amount) as Turnover from Customer c inner join Invoice i on i.CustomerID = c.ID group by c.ID, c.Name, c.City having sum(i.Amount) >= ? order by Turnover desc;', 'double', '', '', '', '', '', '', '', '[100.0]', 1, 0);
